async function importJSON(e){const file=e.target.files?.[0];if(!file)return;try{const d=JSON.parse(await file.text());if(!Array.isArray(d.stories)||!Array.isArray(d.videos))throw Error("Sai cấu trúc");if(!confirm("Nhập bản sao lưu sẽ thay dữ liệu hiện tại trên trình duyệt. Bà đã xuất bản sao lưu hiện tại chưa?"))return;data={...seed,...d};if(save()){toast("Đã khôi phục dữ liệu");go("admin")}}catch{toast("Tệp JSON không hợp lệ hoặc không phải bản sao lưu THƯ CÁ")}e.target.value=""}

// Video files are kept in IndexedDB on this browser/device, not in Google Drive.
const VIDEO_DB="thuca-video-files",VIDEO_STORE="files";
function openVideoDB(){return new Promise((resolve,reject)=>{if(!("indexedDB" in window)){reject(new Error("Trình duyệt không hỗ trợ lưu video"));return}const req=indexedDB.open(VIDEO_DB,1);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains(VIDEO_STORE))req.result.createObjectStore(VIDEO_STORE)};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error||new Error("Không mở được bộ nhớ video"))})}
