function filterVideoLibrary(){const q=($("#video-search")?.value||"").toLowerCase(),kind=$("#video-kind-filter")?.value||"";document.querySelectorAll(".cinema-tile").forEach(card=>{const id=card.querySelector("[data-open-feed]")?.dataset.openFeed,v=data.videos.find(x=>x.id===id);card.hidden=!!v&&(!((v.title+" "+(v.note||"")).toLowerCase().includes(q))||(kind&&v.kind!==kind))})}
let feedObserver=null,feedUrls=new Map(),feedActiveId=null;
function releaseFeedPlayers(){if(feedObserver)feedObserver.disconnect();feedObserver=null;document.querySelectorAll(".feed-video").forEach(v=>{v.pause();v.removeAttribute("src");v.load()});feedUrls.forEach(u=>URL.revokeObjectURL(u));feedUrls.clear();feedActiveId=null}
async function prepareFeedVideo(item){const id=item.dataset.videoId,v=data.videos.find(x=>x.id===id),player=item.querySelector(".feed-video");if(!v||!player)return null;if(!player.src){let src=v.url||"";if(v.fileStored){try{const blob=await getVideoBlob(id);if(blob)src=URL.createObjectURL(blob);else if(v.storagePath&&window.TCCloudSync?.isConnected)src=await window.TCCloudSync.getVideoUrl(v.storagePath);else{toast("Video này chưa có bản lưu trên thiết bị hoặc đám mây.");return null}feedUrls.set(id,src)}catch(e){toast("Không đọc được video: "+(e.message||"lỗi tải tệp"));return null}}if(!src||/youtube\.com|youtu\.be|vimeo\.com|drive\.google\.com/i.test(src)){item.classList.add("feed-embed-only");return null}player.src=src;player.load()}return player}
async function activateFeedItem(item){const id=item.dataset.videoId;if(feedActiveId===id)return;document.querySelectorAll(".feed-item").forEach(x=>{const p=x.querySelector("video");if(p){p.pause();x.classList.remove("is-playing")}});feedActiveId=id;const player=await prepareFeedVideo(item);if(!player||feedActiveId!==id)return;player.muted=true;const result=player.play();if(result&&result.catch)result.catch(()=>item.classList.add("feed-needs-tap"));item.classList.add("is-playing");const v=data.videos.find(x=>x.id===id);updateFeedSubtitle(v,item)}
function wireVideoFeed(startId){const feed=$("#video-feed");if(!feed)return;if(feedObserver)feedObserver.disconnect();const items=[...feed.querySelectorAll(".feed-item")];if(!items.length)return;const start=startId?items.find(x=>x.dataset.videoId===startId):items[0];if(start&&start!==items[0])feed.scrollTop=items.indexOf(start)*feed.clientHeight;feedObserver=new IntersectionObserver(entries=>{const best=entries.filter(e=>e.isIntersecting).sort((a,b)=>b.intersectionRatio-a.intersectionRatio)[0];if(best&&best.intersectionRatio>=.62)activateFeedItem(best.target)},{root:feed,threshold:[.25,.45,.62,.8]});items.forEach(x=>feedObserver.observe(x));if(start)activateFeedItem(start);feed.onclick=e=>{const tab=e.target.closest("[data-cinema-tab]");if(tab){switchCinemaTab(tab.dataset.cinemaTab);return}const toggle=e.target.closest("[data-feed-toggle]");if(toggle){toggleFeedVideo(toggle.dataset.feedToggle);return}const sound=e.target.closest("[data-feed-sound]");if(sound){toggleFeedSound(sound.dataset.feedSound);return}const sub=e.target.closest("[data-feed-sub]");if(sub){showFeedSubtitleMenu(sub.dataset.feedSub);return}const external=e.target.closest("[data-play-video]");if(external){playVideo(external.dataset.playVideo);return}const edit=e.target.closest("[data-edit-video]");if(edit){openVideoEditor(edit.dataset.editVideo);return}};feed.onkeydown=e=>{if(e.key==="ArrowDown"||e.key==="PageDown"){e.preventDefault();feed.scrollBy({top:feed.clientHeight,behavior:"smooth"})}if(e.key==="ArrowUp"||e.key==="PageUp"){e.preventDefault();feed.scrollBy({top:-feed.clientHeight,behavior:"smooth"})}}}
function toggleFeedVideo(id){const item=document.querySelector('[data-video-id="'+CSS.escape(id)+'"]'),p=item?.querySelector("video");if(!item||!p)return;if(p.paused){p.play().then(()=>item.classList.add("is-playing")).catch(()=>toast("Video chưa thể phát. Kiểm tra đường dẫn hoặc tệp video."))}else{p.pause();item.classList.remove("is-playing")}}
function toggleFeedSound(id){const item=document.querySelector('[data-video-id="'+CSS.escape(id)+'"]'),p=item?.querySelector("video");if(!item||!p)return;p.muted=!p.muted;if(p.muted){item.classList.add("feed-muted")}else{item.classList.remove("feed-muted");p.play().catch(()=>{})}}
function updateFeedSubtitle(v,item){const box=item.querySelector(".feed-subtitle"),player=item.querySelector("video");if(!box||!v||!player)return;const update=()=>{const t=player.currentTime,sub=(v.subtitles||[]).find(x=>t>=subtitleSeconds(x.start)&&t<=subtitleSeconds(x.end)),mode=box.dataset.mode||"vi";box.innerHTML=!sub||mode==="off"?"":mode==="both"?'<span>'+esc(sub.original||"")+'</span><span>'+esc(sub.vi||"")+'</span>':esc(mode==="original"?(sub.original||""):(sub.vi||sub.original||""))};player.addEventListener("timeupdate",update);update()}
function showFeedSubtitleMenu(id){const v=data.videos.find(x=>x.id===id),item=document.querySelector('[data-video-id="'+CSS.escape(id)+'"]');if(!v||!item)return;if(!(v.subtitles||[]).length){toast("Video này chưa có phụ đề.");return}const box=item.querySelector(".feed-subtitle"),modes=["vi","original","both","off"],labels={vi:"Tiếng Việt",original:"Tiếng Trung",both:"Song ngữ",off:"Tắt phụ đề"},current=box.dataset.mode||"vi",mode=modes[(modes.indexOf(current)+1)%modes.length];box.dataset.mode=mode;updateFeedSubtitle(v,item);toast("Phụ đề: "+labels[mode])}
function subtitleSeconds(value){const p=String(value||"").replace(",",".").split(":").map(Number);if(p.length===3)return p[0]*3600+p[1]*60+p[2];if(p.length===2)return p[0]*60+p[1];return Number(value)||0}
function wirePlayerSubtitles(v){const player=$("#thu-ca-player"),overlay=$("#video-subtitle-overlay"),select=$("#subtitle-track");if(!player||!overlay||!select)return;const update=()=>{const mode=select.value;if(mode==="off"){overlay.textContent="";return}const t=player.currentTime,sub=(v.subtitles||[]).find(x=>t>=subtitleSeconds(x.start)&&t<=subtitleSeconds(x.end));if(!sub){overlay.textContent="";return}const vi=sub.vi||"",original=sub.original||"";overlay.innerHTML=mode==="both"?('<span>'+esc(original)+'</span>'+(vi?'<span>'+esc(vi)+'</span>':"")):esc(mode==="original"?original:vi||original)};player.addEventListener("timeupdate",update);player.addEventListener("seeked",update);player.addEventListener("loadedmetadata",update);select.addEventListener("change",update);update()}
