function subtitleEditor(v){return '<div class="admin-panel" id="subtitle-editor"><h2>Phụ đề — '+esc(v.title)+'</h2><p class="page-desc">Nhận diện chữ Trung đã in sẵn trên hình bằng OCR ngay trong trình duyệt. OCR chỉ trích xuất chữ và thời gian; phần dịch chất lượng cao thực hiện trong ChatGPT, không cần API trả phí.</p><div class="notice"><b>Lưu ý:</b> Video cần phát được trên thiết bị. Mặc định quét vùng 30% phía dưới khung hình, mỗi 1 giây. Lần đầu cần tải bộ nhận diện tiếng Trung từ CDN; video dài hoặc điện thoại yếu có thể xử lý chậm.</div><div class="field"><label>Ngôn ngữ phụ đề Trung</label><select id="ocr-language"><option value="chi_sim">Tiếng Trung giản thể</option><option value="chi_tra">Tiếng Trung phồn thể</option></select></div><div class="field"><label>Tần suất lấy khung hình</label><select id="ocr-interval"><option value="1">Mỗi 1 giây (khuyến nghị)</option><option value="0.5">Mỗi 0,5 giây (chậm hơn, dễ bắt câu ngắn)</option><option value="1.5">Mỗi 1,5 giây (nhanh hơn)</option></select></div><div class="form-actions"><button type="button" class="primary-btn" id="start-video-ocr">Nhận diện phụ đề Trung</button><button type="button" class="secondary-btn" id="copy-ocr-text">Sao chép bản Trung để dịch</button></div><p id="ocr-status" class="page-desc">Chưa chạy OCR.</p><div class="field"><label>Dán bản dịch tiếng Việt theo đúng thứ tự, mỗi câu một dòng</label><textarea id="ocr-translation-paste" rows="6" placeholder="Dán các câu tiếng Việt đã dịch từ ChatGPT vào đây..."></textarea></div><button type="button" class="secondary-btn" id="apply-ocr-translation">Ghép bản dịch vào từng câu</button><hr><div class="field"><label>Nhập tệp SRT hoặc VTT có sẵn</label><input id="subtitle-file" type="file" accept=".srt,.vtt,text/vtt"></div><div class="field"><label>Hoặc dán nội dung SRT/VTT</label><textarea id="subtitle-paste" rows="6" placeholder="1&#10;00:00:01,000 --> 00:00:03,000&#10;Original subtitle"></textarea></div><button class="secondary-btn" id="parse-subtitles">Đọc phụ đề</button><div id="subtitle-rows"></div><div class="form-actions"><button class="primary-btn" id="save-subtitles">Lưu phụ đề</button><button class="secondary-btn" id="download-srt">Tải SRT tiếng Việt</button><button class="secondary-btn" id="download-vtt">Tải VTT tiếng Việt</button></div></div>'}
function wireSubtitle(v){let list=[...(v.subtitles||[])];videoDraftSubtitles=list;wireVideoOCR(v);$("#subtitle-file").onchange=async e=>{let f=e.target.files[0];if(f)$("#subtitle-paste").value=await f.text()};$("#parse-subtitles").onclick=()=>{list=parseSubtitleText($("#subtitle-paste").value);videoDraftSubtitles=list;renderSubtitleRows(list)};$("#save-subtitles").onclick=()=>{list=readSubtitleRows();v.subtitles=list;if(save())toast("Đã lưu phụ đề")};$("#download-srt").onclick=()=>downloadSubtitle(readSubtitleRows(),"srt");$("#download-vtt").onclick=()=>downloadSubtitle(readSubtitleRows(),"vtt");if(list.length)renderSubtitleRows(list)}

// OCR phụ đề in sẵn trên hình video. Không gửi video lên máy chủ.
let ocrCancelled=false;
function secondsToSrt(n){const ms=Math.max(0,Math.round(n*1000)),h=Math.floor(ms/3600000),m=Math.floor(ms%3600000/60000),sec=Math.floor(ms%60000/1000),z=ms%1000;return [h,m,sec].map(x=>String(x).padStart(2,"0")).join(":")+","+String(z).padStart(3,"0")}
function waitVideoSeek(video,t){return new Promise((resolve,reject)=>{const done=()=>{cleanup();resolve()},fail=()=>{cleanup();reject(new Error("Không tua được video"))},cleanup=()=>{video.removeEventListener("seeked",done);video.removeEventListener("error",fail)};video.addEventListener("seeked",done,{once:true});video.addEventListener("error",fail,{once:true});video.currentTime=t;if(Math.abs(video.currentTime-t)<.03&&video.readyState>=2){cleanup();resolve()}})}
function loadTesseract(){return new Promise((resolve,reject)=>{if(window.Tesseract)return resolve(window.Tesseract);const script=document.createElement("script");script.src="https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js";script.onload=()=>window.Tesseract?resolve(window.Tesseract):reject(new Error("Không tải được thư viện OCR"));script.onerror=()=>reject(new Error("Không tải được thư viện OCR. Kiểm tra kết nối mạng."));document.head.appendChild(script)})}
async function wireVideoOCR(v){
 const run=$("#start-video-ocr"),status=$("#ocr-status");if(!run)return;
 run.onclick=async()=>{
  if(run.dataset.running==="1"){ocrCancelled=true;run.textContent="Đang dừng...";return}
  run.dataset.running="1";run.textContent="Dừng OCR";ocrCancelled=false;
  let objectUrl="",worker=null,video=null;
  try{
   status.textContent="Đang mở video...";
   let src=v.url||"";
   if(v.fileStored){const blob=await getVideoBlob(v.id);if(blob){objectUrl=URL.createObjectURL(blob);src=objectUrl}else if(v.storagePath&&window.TCCloudSync?.isConnected){src=await window.TCCloudSync.getVideoUrl(v.storagePath)}else throw new Error("Không tìm thấy video trên thiết bị hoặc trong kho đám mây.")}
   if(!src||/youtube\.com|youtu\.be|vimeo\.com|drive\.google\.com/i.test(src))throw new Error("OCR hiện chỉ xử lý video tải trực tiếp lên THƯ CÁ hoặc URL video trực tiếp MP4/WebM; video nhúng YouTube/Vimeo không hỗ trợ.");
   video=document.createElement("video");video.muted=true;video.playsInline=true;video.preload="auto";if(objectUrl)video.src=src;else{video.crossOrigin="anonymous";video.src=src}
   await new Promise((resolve,reject)=>{video.onloadedmetadata=resolve;video.onerror=()=>reject(new Error("Trình duyệt không đọc được video này."));video.load()});
   if(video.readyState<2)await new Promise((resolve,reject)=>{video.addEventListener("loadeddata",resolve,{once:true});video.addEventListener("error",()=>reject(new Error("Không tải được khung hình đầu tiên")), {once:true})});
   if(!Number.isFinite(video.duration)||video.duration<=0)throw new Error("Không xác định được thời lượng video.");
   if(video.duration>1800)throw new Error("Bản OCR hiện giới hạn video tối đa 30 phút để tránh treo trình duyệt. Hãy chia video thành đoạn ngắn.");
   const interval=Number($("#ocr-interval").value)||1,lang=$("#ocr-language").value;
   status.textContent="Đang tải bộ nhận diện chữ Trung...";
   const T=await loadTesseract();worker=await T.createWorker(lang);
   const canvas=document.createElement("canvas"),ctx=canvas.getContext("2d",{willReadFrequently:true}),found=[];
   const total=Math.ceil(video.duration/interval);
   for(let i=0;i<total;i++){
    if(ocrCancelled)break;
    const t=Math.min(i*interval,Math.max(0,video.duration-.05));
    await waitVideoSeek(video,t);
    if(video.videoWidth===0||video.videoHeight===0)continue;
    const cropH=Math.round(video.videoHeight*.32),cropY=video.videoHeight-cropH;
    canvas.width=Math.min(1600,video.videoWidth);canvas.height=Math.round(cropH*canvas.width/video.videoWidth);
    ctx.drawImage(video,0,cropY,video.videoWidth,cropH,0,0,canvas.width,canvas.height);
    const result=await worker.recognize(canvas);
    const text=(result.data.text||"").replace(/\s+/g," ").trim();
    const confidence=result.data.confidence||0;
    if(text.length>0&&confidence>=20){
     const last=found[found.length-1];
     if(last&&last.original===text&&t-last._last<=interval*1.6){last.end=secondsToSrt(Math.min(video.duration,t+interval));last._last=t}
     else found.push({start:secondsToSrt(t),end:secondsToSrt(Math.min(video.duration,t+interval)),original:text,vi:"",_last:t});
    }
    status.textContent="Đang nhận diện: "+Math.min(i+1,total)+"/"+total+" khung hình · tìm được "+found.length+" dòng.";
   }
   found.forEach(x=>delete x._last);
   if(found.length){videoDraftSubtitles=found;v.subtitles=found;const saved=save();renderSubtitleRows(found);status.textContent=(ocrCancelled?"Đã dừng. ":"Hoàn tất. ")+ "Nhận diện được "+found.length+" dòng."+(saved?" Đã tự lưu bản phụ đề gốc vào video.":" Không lưu được: bộ nhớ trình duyệt có thể đã đầy.")+" Bà có thể mở video để xem chữ Trung ngay, hoặc dịch sang tiếng Việt rồi lưu tiếp."}
   else status.textContent=ocrCancelled?"Đã dừng OCR. Chưa tìm thấy dòng phụ đề.":"Không nhận diện được chữ. Thử chọn đúng ngôn ngữ hoặc dùng video rõ nét hơn.";
  }catch(err){status.textContent="OCR chưa hoàn tất: "+(err.message||"Lỗi không xác định")}
  finally{if(worker)try{await worker.terminate()}catch{}if(objectUrl)URL.revokeObjectURL(objectUrl);run.dataset.running="";run.textContent="Nhận diện phụ đề Trung";ocrCancelled=false}
 };
 $("#copy-ocr-text").onclick=async()=>{const text=readSubtitleRows().map(x=>x.original).join("\n");if(!text.trim()){toast("Chưa có nội dung OCR để sao chép");return}try{await navigator.clipboard.writeText(text);toast("Đã sao chép danh sách phụ đề Trung")}catch{ $("#ocr-translation-paste").value="";toast("Trình duyệt chưa cho phép sao chép tự động")}};
 $("#apply-ocr-translation").onclick=()=>{const lines=$("#ocr-translation-paste").value.replace(/\r/g,"").split("\n").map(x=>x.trim()).filter(Boolean),rows=readSubtitleRows();if(!rows.length){toast("Chưa có phụ đề OCR");return}if(lines.length!==rows.length){toast("Số dòng dịch phải khớp số dòng phụ đề Trung ("+rows.length+").");return}rows.forEach((x,i)=>x.vi=lines[i]);videoDraftSubtitles=rows;v.subtitles=rows;const saved=save();renderSubtitleRows(rows);toast(saved?"Đã ghép và lưu bản dịch vào video.":"Đã ghép bản dịch nhưng lưu thất bại; hãy bấm Lưu phụ đề.")};
}
function parseSubtitleText(raw){const blocks=raw.replace(/\r/g,"").replace(/^WEBVTT[^\n]*\n/,"").trim().split(/\n\s*\n/);return blocks.map(b=>{let l=b.split("\n").filter(Boolean),ti=l.findIndex(x=>x.includes("-->"));if(ti<0)return null;let t=l[ti].split("-->");return {start:t[0].trim().replace(".",","),end:t[1].trim().split(/\s+/)[0].replace(".",","),original:l.slice(ti+1).join("\n"),vi:""}}).filter(Boolean)}
function renderSubtitleRows(list){videoDraftSubtitles=list;$("#subtitle-rows").innerHTML='<h3>'+list.length+' dòng phụ đề</h3>'+list.map((s,i)=>'<div class="subtitle-row"><small>'+esc(s.start)+' → '+esc(s.end)+'</small><div class="field"><label>Bản gốc</label><textarea data-sub-original="'+i+'" rows="2">'+esc(s.original)+'</textarea></div><div class="field"><label>Bản tiếng Việt</label><textarea data-sub-vi="'+i+'" rows="2" placeholder="Nhập bản dịch tiếng Việt...">'+esc(s.vi)+'</textarea></div></div>').join("")}
function readSubtitleRows(){return [...document.querySelectorAll("[data-sub-vi]")].map(el=>{let i=Number(el.dataset.subVi),o=$('[data-sub-original="'+i+'"]');return {...videoDraftSubtitles[i],original:o.value,vi:el.value}})}
function downloadSubtitle(list,format){let body=format==="vtt"?"WEBVTT\n\n":"";body+=list.map((s,i)=>(format==="srt"?(i+1)+"\n":"")+s.start.replace(",",".")+" --> "+s.end.replace(",",".")+"\n"+(s.vi||s.original)).join("\n\n");const blob=new Blob([body],{type:"text/plain;charset=utf-8"}),a=document.createElement("a"),url=URL.createObjectURL(blob);a.href=url;a.download="thu-ca-subtitles."+format;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
window.THUCAS_DATA_BRIDGE={
 getData:()=>data,
 getPersonalData:()=>({shelf:[...(data.shelf||[])],progress:{...(data.progress||{})},updatedAt:data.personalUpdatedAt||new Date().toISOString()}),
 setPersonalData:personal=>{
  data.shelf=Array.isArray(personal?.shelf)?personal.shelf:[];
  data.progress=personal?.progress&&typeof personal.progress==="object"?personal.progress:{};
  data.personalUpdatedAt=personal?.updatedAt||new Date().toISOString();
  lastSavedSnapshot=JSON.stringify(data);
  try{localStorage.setItem(KEY,lastSavedSnapshot)}catch{}
  render();
 },
 getVideoBlob,
 setData:next=>{
  const personal={shelf:data.shelf||[],progress:data.progress||{},personalUpdatedAt:data.personalUpdatedAt};
  data={...next,...personal};
  lastSavedSnapshot=JSON.stringify(data);
  try{localStorage.setItem(KEY,lastSavedSnapshot)}catch{}
  if(activeStory)activeStory=data.stories.find(s=>s.id===activeStory.id)||activeStory;
  $("#storage-indicator").textContent="Đã nhận thư viện chung";
  render();
 }
};
$("#open-admin").onclick=()=>go("admin");$("#mobile-menu").onclick=()=>$("#sidebar").classList.toggle("open");$("#global-search").addEventListener("keydown",e=>{if(e.key==="Enter"){go("stories");const f=$("#story-filter");if(f){f.value=e.target.value;filterStories()}}});$("#profile-btn").onclick=()=>{go("admin");document.querySelector('[data-admin-tab="backup"]')?.click()};document.querySelectorAll("[data-nav]").forEach(a=>a.onclick=e=>{e.preventDefault();go(a.dataset.nav)});go("home");
